  "agent.api_max_retries": {"type":"int","default":3,"doc":"Hermes-level retry attempts for API errors (connection drops, timeouts, 5xx) wrapping the whole call; the OpenAI SDK also retries transient errors (max_retries=2). Set 1 for fast failover to fallback providers; raise to tolerate longer provider hiccups.","group":"agent","effect":"session"},
  "agent.auto_recovery_cycles": {"type":"int","default":5,"doc":"Once api_max_retries AND the fallback chain are spent on a transient outage (5xx, overloaded/529, connect/read timeouts) with nothing delivered yet, wait and retry this many more cycles (jittered 15/30/60/60/60s; a provider Retry-After wins up to 120s) with a visible \"retrying automatically\" countdown instead of ending the turn. Esc/interrupt stops the wait; auth/format/billing/policy errors never enter. 0 disables.","group":"agent","effect":"session"},
