  "agent.build_wait_timeout": {"type":"int","default":600,"doc":"Max seconds a submitted prompt waits for the deferred agent build (MCP discovery, model metadata, skills scan) before failing visibly. The prompt is delivered as soon as the build completes (progress notice past 30s), so this only fires on a hung build. Raise for many slow/unreachable MCP servers. See #63078.","group":"agent","effect":"session"},
  "agent.clarify_timeout": {"type":"int","default":3600,"doc":"Max seconds any surface (CLI, TUI/Desktop, messaging gateway) blocks an agent awaiting a clarify-tool reply; then it unblocks with \"[user did not respond within Xm]\". 0 or less = unlimited. Resolved by tools/clarify_gateway.py::resolve_clarify_timeout (a legacy top-level ``clarify.timeout`` still wins when explicitly set). 1h because users step away and a shorter value evicted the entry mid-think so a later button tap hit a dead entry. Tradeoff: a higher value holds the gateway's running-agent guard longer for a genuinely abandoned prompt — lower it to free the guard sooner. See #32762.","group":"agent","effect":"session"},
  "agent.coding_context": {"type":"str","default":"auto","doc":"Coding posture: on interactive coding surfaces (CLI, TUI, desktop, ACP) in a code workspace, add a coding brief + live git/workspace snapshot to the system prompt (agent/coding_context.py). \"auto\" = prompt-only when interactive AND cwd is a code workspace (toolsets untouched, messaging platforms unaffected); \"focus\" = auto + collapse toolset to the lean coding set (+ enabled MCP servers) + demote non-coding skill categories to names-only (explicit opt-in); \"on\" = force everywhere; \"off\" = disable.","group":"agent","effect":"session"},
  "agent.coding_instructions": {"type":"str","default":"","doc":"Standing operator instructions (string or list) appended to the coding brief as an extra stable system block — project-wide workflow rules, e.g. \"Don't run tsc/lint until I approve.\" Cache-safe: takes effect next session.","group":"agent","effect":"session"},
  "agent.cron_drain_timeout": {"type":"int","default":30,"doc":"Floor under the stop()/drain wait (seconds) for cron jobs and api_server runs. Interrupted chat turns resume on the next message, but an interrupted cron run is recorded as a permanent failure and an interrupted /v1 run fails its waiting caller, so neither may inherit restart_drain_timeout's 0 (#82161, #132989). Clamped to the shutdown-watchdog leash minus teardown headroom (~50s unless TimeoutStopSec is raised). 0 = opt out.","group":"agent","effect":"session"},
