  "agent.empty_response_guard.enabled": {"type":"bool","default":true,"doc":"False = legacy fixed 3 retries unconditionally","group":"agent","effect":"session"},
  "agent.environment_hint": {"type":"str","default":"","doc":"Embedder-supplied text appended to the system prompt's environment-hints block, so a host wrapping Hermes (sandbox runner, managed platform) can describe proxy/credential/ mount layout without editing SOUL.md. Env HERMES_ENVIRONMENT_HINT overrides it.","group":"agent","effect":"session"},
  "agent.environment_probe": {"type":"bool","default":true,"doc":"Toolchain probe: surfaces Python/pip/uv/PEP-668 state in the system prompt only when something non-default is detected (no pip module, pip/python mismatch, PEP 668 without uv); zero tokens when clean. Skipped for docker/modal/ssh backends (own probe).","group":"agent","effect":"session"},
  "agent.execution_guidance": {"type":"str","default":"auto","doc":"Execution-discipline prompt block (tool persistence, tools for arithmetic/system facts, read-back after external writes, count reconciliation, literal identifiers, verification-gated completion). Chosen once per session by model name (byte-stable). \"auto\" = gpt/codex/grok/deepseek/kimi/qwen/glm/minimax/mimo/mistral; true/false = force; or a list of model-name substrings.","group":"agent","effect":"session"},
  "agent.fast_auto_seconds": {"type":"int","default":60,"doc":"","group":"agent","effect":"session"},
  "agent.gateway_auto_continue_freshness": {"type":"int","default":3600,"doc":"Freshness window (seconds) for the auto-continue note. After a crash/restart mid-run the next user message gets \"[System note: your previous turn was interrupted...]\" prepended; only when the last persisted transcript row is younger than this, so stale markers don't revive an unrelated old task. Covers gateway_timeout (1800) plus slack. 0 = always inject.","group":"agent","effect":"session"},
  "agent.gateway_notify_interval": {"type":"int","default":180,"doc":"\"Still working\" status interval (seconds); 0 = off. Lower = faster feedback, more noise; 180 catches spinning weak-model runs before users /restart.","group":"agent","effect":"session"},
  "agent.gateway_startup_restore_drain_timeout": {"type":"int","default":30,"doc":"Max seconds the gateway waits for boot auto-resume turns before releasing the startup-restore inbound gate (all inbound is QUEUED while shut, so one long resumed turn would leave every channel unanswered). On timeout the gate opens and the resume keeps running in the background; duplicate-agent protection is unaffected because the resume slot is claimed synchronously first. 0 = wait forever.","group":"agent","effect":"session"},
  "agent.gateway_startup_warmup_timeout": {"type":"int","default":20,"doc":"Max seconds the boot turn-machinery warm-up (run_agent import graph, tool schemas + availability probes, context-file tier) may hold the inbound gate shut, so an early message isn't served with a skeleton system prompt. On timeout the gate opens and warm-up finishes in the background. 0 = disable warm-up (lazy init).","group":"agent","effect":"session"},
  "agent.gateway_timeout": {"type":"int","default":1800,"doc":"Gateway inactivity timeout (seconds). Only fires when the agent is completely idle — not while calling tools or receiving API responses. 0 = unlimited.","group":"agent","effect":"session"},
  "agent.gateway_timeout_warning": {"type":"int","default":900,"doc":"Inactivity warning (seconds), once per run before gateway_timeout; no interrupt. 0 = off.","group":"agent","effect":"session"},
  "agent.gateway_turn_lease_timeout": {"type":"int","default":5,"doc":"Max seconds an alias routing key waits for the active turn holding the same session lease; on expiry the message is rejected with a resend notice. Keep short: Telegram dispatches sequentially, so a waiter delays unrelated topics. Non-positive -> 5s.","group":"agent","effect":"session"},
  "agent.image_input_mode": {"type":"str","default":"auto","doc":"How user-attached images reach the main model (gateway, TUI, CLI /attach). \"auto\" = native when the model reports supports_vision=True AND auxiliary.vision.provider is not explicitly set, else text; \"native\" = always attach (non-vision models error at the provider or get a last-chance text fallback); \"text\" = always pre-analyze with vision_analyze and prepend the description. vision_analyze stays a tool regardless.","group":"agent","effect":"session"},
  "agent.intent_ack_continuation": {"type":"str","default":"auto","doc":"When the model narrates an action (\"I'll go check the logs...\") but emits no tool call, inject a \"continue now, execute the tools\" nudge and loop (max 2 nudges/turn). Corrective sibling of tool_use_enforcement. \"auto\" = codex_responses api_mode only; true = all api_modes (fixes Gemini/Claude \"stops after stating intent\"); false = never; or a list of model-name substrings.","group":"agent","effect":"session"},
  "agent.local_stream_stale_timeout": {"type":"int","default":900,"doc":"Stale-stream ceiling (seconds) for local providers (Ollama, oMLX, llama-cpp). Applied when the base stale timeout is at its 180s default and a local endpoint is detected, so a wedged local server eventually trips the detector instead of hanging forever. Env HERMES_LOCAL_STREAM_STALE_TIMEOUT overrides.","group":"agent","effect":"session"},
  "agent.max_turns": {"type":"null","default":null,"doc":"Turn cap. null = unlimited (default; caps caused silent mid-task truncation). Positive int caps; \"none\"/\"unlimited\"/\"inf\"/0/-1 also mean unlimited (resolve_turn_limit).","group":"agent","effect":"session"},
