  "agent.reasoning_echo": {"type":"bool","default":false,"doc":"Stored reasoning is replayed to every provider that can read it by default. This flag only adds the must-echo \" \" pad on reasoning-less tool-call turns, which DeepSeek, Kimi/Moonshot and Xiaomi MiMo require (auto-detected by provider name/host). Set `reasoning_echo: true` on a `model:` or `fallback_providers:` entry for a custom gateway proxying one of them. Strict providers (Mistral, Groq, Cerebras) never get the field.","group":"agent","effect":"session"},
