  "agent.reconnect_attention_after": {"type":"int","default":7200,"doc":"Seconds of continuous reconnect failure before a platform gets needs_attention flagged in gateway status (`hermes status` / fleet monitoring). Retries never stop — a signal, not a circuit breaker. 0 = disable.","group":"agent","effect":"session"},
  "agent.restart_after_turn_timeout": {"type":"int","default":1800,"doc":"In-band restart (/restart, SIGUSR1): refuse new work, then wait up to this many seconds for in-flight agents/cron/api runs to finish before stop(). 0 = enter stop() at once. 30 min is a safety valve for wedged agents, not a target; raise for long unattended turns. Default 30 min is a safety valve for wedged agents, not a target latency — an interactive `hermes gateway restart` must never block for hours on a turn that wedged (#79133).","group":"agent","effect":"session"},
  "agent.restart_drain_timeout": {"type":"int","default":0,"doc":"Force-interrupt budget (seconds) once gateway stop()/drain has begun (SIGTERM, and the final phase of in-band restart). 0 = interrupt immediately. Keep under systemd TimeoutStopSec or risk SIGKILL mid-cleanup; for /restart prefer restart_after_turn_timeout so turns finish BEFORE stop().","group":"agent","effect":"session"},
  "agent.run_budget_seconds": {"type":"null","default":null,"doc":"Wall-clock budget (seconds) per run. null = off. When set: one-time wrap-up notice at 80% elapsed; implicit provider stale timeouts capped to remaining budget. CLI equivalent: `hermes chat --run-budget N`.","group":"agent","effect":"session"},
  "agent.sanitizer_heal_escalation_threshold": {"type":"int","default":3,"doc":"Transcript-sanitiser heal escalation: after this many pre-send heal passes within a 10-minute window, log one ERROR and queue a ONE-TIME out-of-band notice pointing at /debug share or `hermes doctor` (status channel only; prompt cache untouched). 0 = no escalation (per-window WARNINGs still fire). See #96870.","group":"agent","effect":"session"},
  "agent.service_tier": {"type":"str","default":"","doc":"Fast mode: \"\" / \"normal\" (off), \"fast\" (always), \"auto\" (first fast_auto_seconds of every turn), \"cold\" (first turn of a session only).","group":"agent","effect":"live"},
  "agent.session_stall_timeout": {"type":"int","default":300,"doc":"Session stall watchdog (seconds): RECOVERY notifier for an in-process AIAgent with an adapter-queued follow-up while its activity clock is stale — NOT a general stall detector (ignores startup restore, build sentinels, leases, debounce, other processes; scan cadence per AIAgent). Notify-only: tells the user to try /new. Distinct from gateway_timeout (kills the turn) and gateway_notify_interval. 0 = disable. See #76354.","group":"agent","effect":"session"},
  "agent.stall_guards": {"type":"bool","default":true,"doc":"Anti-stall guards: (1) identical-call loop breaker appends a notice when the same tool is called 3+ times with identical args AND results (never blocks; pollers like `process` exempt); (2) continue-intent extension of empty-response recovery re-prompts once when the model says it will continue but takes no action. False disables both.","group":"agent","effect":"session"},
  "agent.stream_drain_timeout": {"type":"float","default":2,"doc":"Seconds the Codex/Responses stream may keep reading after its terminal frame so the relay finalizer can run. Relays that never close the SSE socket after response.completed would otherwise wedge the turn until the idle watchdog discards the already-billed response (#103864). 0 skips the drain. Well-behaved endpoints close immediately and never wait this long.","group":"agent","effect":"session"},
