  "agent.tool_use_enforcement": {"type":"str","default":"auto","doc":"System-prompt guidance telling the model to call tools instead of describing actions. \"auto\" = gpt/codex models; true/false = force for all models; or a list of model-name substrings (e.g. [\"gpt\", \"codex\", \"gemini\", \"qwen\"]).","group":"agent","effect":"session"},
