  "agent.verify_guidance": {"type":"bool","default":true,"doc":"When verify-on-stop finds edits without fresh verification evidence, add guidance for creative UI work (no broad tsc/lint/test before visual approval) and clean-diff expectations. false = keep the evidence nudge terse.","group":"agent","effect":"session"},
  "agent.verify_on_stop": {"type":"bool","default":false,"doc":"Verification closure: after code edits in a workspace, refuse a final answer until fresh verification evidence exists or the agent explains why it can't check (bounded loop, passive ledger). False (default) because the nudges proved more noise than signal; true = force on everywhere; \"auto\" = on for interactive coding surfaces and programmatic callers, off for messaging surfaces. Doc/markdown/skill-only edits never fire.","group":"agent","effect":"session"},
