  "approvals.mcp_reload_confirm": {"type":"bool","default":true,"doc":"/reload-mcp confirms before rebuilding the MCP tool set (it invalidates the prompt cache, so the next message re-sends full input). \"Always Approve\" → false.","group":"approvals","effect":"live"},
  "approvals.mode": {"type":"str","default":"smart","doc":"single_query_mode — what to do when a single-query (-q) session hits a dangerous command. -q runs export HERMES_INTERACTIVE=1 (for interactive sudo prompts) but have NO user waiting to answer approval prompts — an unanswered prompt just waits the full timeout then fails closed, so the agent is forced to work around the block (often via execute_code). This setting makes that intent explicit: deny    — block the command and let the agent find another way (default, safe; mirrors cron_mode deny) approve — auto-approve all dangerous commands in single-query mode These surfaces bind a session platform like chat gateways do, but have no send_exec_approval and no /approve channel — a pending approval there just blocks for the full timeout with nobody to answer (#37284, #87509): deny    — block the command instantly and let the agent find another way (default, safe; mirrors cron_mode deny) approve — auto-approve all dangerous commands on unattended platforms Shared by the CLI prompt and gateway/messaging waits. Messaging approvals arrive as a push notification the user may not see immediately — 60s proved too tight on Telegram/Discord (the prompt expired before the user reached their phone), so the default is 300.","group":"approvals","effect":"live"},
