  "auth.adopt_external_logins": {"type":"bool","default":true,"doc":"Borrow and refresh the Codex CLI (~/.codex/auth.json) and Claude Code (~/.claude/.credentials.json) logins automatically when Hermes has no usable login of its own. Their refresh tokens are single-use and rotate, so two programs on one login can log each other out; set false to make Hermes use only its own logins (`hermes auth add <provider>`). `hermes auth add openai-codex` still offers the import interactively.","group":"auth","effect":"live"},
  "auth.codex_login_flow": {"type":"str","default":"device_code","doc":"How `hermes auth add openai-codex` / `hermes model` sign in to OpenAI Codex. \"device_code\" (default): open a URL, enter a code. \"browser\": authorization-code + PKCE on the loopback listener http://localhost:1455/auth/callback (the redirect OpenAI registered for the Codex client) — for organizations that disable the device-code grant. Falls back to device code when that port is busy. `hermes auth add openai-codex --browser` opts in for one login without changing this key.","group":"auth","effect":"live"},
