  "auxiliary.stream_only_base_urls": {"type":"list","default":[],"doc":"Endpoints that reject NON-streaming chat (HTTP 400): aux calls are sent with stream=True and aggregated. Case-insensitive URL substrings; copilot.tencent.com is always stream-only.","group":"auxiliary","effect":"session"},
