  "auxiliary.transient_retries": {"type":"int","default":2,"doc":"Same-provider retries for a transient blip (reset/timeout/5xx/408) on ANY aux call before falling back; clamped [0,6]. Matters for pinned calls (MoA advisors) where provider fallback is not meaningful recovery.","group":"auxiliary","effect":"session"},
