  "slack.free_response_channels": {"type":"str","default":"","doc":"comma-separated channel IDs answered without mention","group":"slack","effect":"live"},
  "slack.ignore_other_user_mentions": {"type":"bool","default":false,"doc":"Ignore messages whose first token @mentions another user unless the bot is also mentioned. Env: SLACK_IGNORE_OTHER_USER_MENTIONS.","group":"slack","effect":"live"},
  "slack.require_mention": {"type":"bool","default":true,"doc":"require @mention to respond in channels","group":"slack","effect":"live"},
  "slack.require_mention_channels": {"type":"str","default":"","doc":"channel IDs where @mention is ALWAYS required","group":"slack","effect":"live"},
  "slack.thread_require_mention": {"type":"bool","default":false,"doc":"require @mention in thread replies too","group":"slack","effect":"live"},
  "streaming.buffer_threshold": {"type":"int","default":24,"doc":"Flush the buffer once this many chars accumulate, so short replies feel instant.","group":"streaming","effect":"live"},
  "streaming.cursor": {"type":"str","default":" ▉","doc":"Cursor glyph appended to the in-progress message.","group":"streaming","effect":"live"},
  "streaming.edit_interval": {"type":"float","default":0.8,"doc":"Minimum seconds between progressive edits (Telegram's ~1 edit/s flood envelope).","group":"streaming","effect":"live"},
  "streaming.enabled": {"type":"bool","default":false,"doc":"When false, each response is delivered as one final message.","group":"streaming","effect":"live"},
  "streaming.fresh_final_after_seconds": {"type":"float","default":0,"doc":"Telegram only: when >0, if the preview was visible at least this many seconds the final edit is sent as a fresh message so the timestamp reflects completion.","group":"streaming","effect":"live"},
  "streaming.transport": {"type":"str","default":"auto","doc":"auto = native drafts where supported (Telegram DMs, Bot API 9.5+), edits elsewhere (Discord, Slack, Matrix, Telegram groups); draft = drafts with edit fallback; edit = progressive editMessageText only; off = disabled.","group":"streaming","effect":"live"},
