  "stt.deepinfra.model": {"type":"str","default":"","doc":"empty = first stt-tagged model from the live catalog","group":"stt","effect":"live"},
  "stt.echo_transcripts": {"type":"bool","default":true,"doc":"Echo the raw transcript of gateway voice messages back as a 🎙️ message.","group":"stt","effect":"live"},
