  "stt.language": {"type":"str","default":"en","doc":"No seeded \"provider\" (a stored value is an explicit pick; unset = autodetect): local | groq | openai | mistral | elevenlabs | deepinfra | xai. Global language hint unless a per-provider one overrides it; \"en\" because Whisper auto-detect misreads short clips; \"\" = auto; \"es\", ...","group":"stt","effect":"live"},
  "stt.local.initial_prompt": {"type":"str","default":"","doc":"","group":"stt","effect":"live"},
  "stt.local.language": {"type":"str","default":"","doc":"auto-detect; set \"en\", \"es\", ... to force","group":"stt","effect":"live"},
  "stt.local.logprob_threshold": {"type":"float","default":-1,"doc":"","group":"stt","effect":"live"},
  "stt.local.model": {"type":"str","default":"base","doc":"tiny, base, small, medium, large-v3, turbo","group":"stt","effect":"live"},
  "stt.local.no_speech_prob_threshold": {"type":"float","default":0.6,"doc":"","group":"stt","effect":"live"},
  "stt.local.unload_after_idle_seconds": {"type":"int","default":0,"doc":"0 = never; e.g. 300 frees the model after 5min","group":"stt","effect":"live"},
  "stt.local.vad": {"type":"bool","default":true,"doc":"Anti-hallucination (faster-whisper decodes junk from silence). vad: Silero filter (false = raw audio, for music/ambient). A segment is dropped only if no_speech_prob ABOVE no_speech_prob_threshold AND avg_logprob BELOW logprob_threshold.","group":"stt","effect":"live"},
  "stt.local.vad_min_silence_ms": {"type":"int","default":500,"doc":"min silence (ms) that splits speech chunks","group":"stt","effect":"live"},
  "stt.mistral.language": {"type":"str","default":"","doc":"auto-detect; set \"en\", \"es\", ... to force","group":"stt","effect":"live"},
  "stt.mistral.model": {"type":"str","default":"voxtral-mini-latest","doc":"voxtral-mini-latest, voxtral-mini-2602","group":"stt","effect":"live"},
  "stt.openai.language": {"type":"str","default":"","doc":"auto-detect; set \"en\", \"es\", ... to force","group":"stt","effect":"live"},
  "stt.openai.max_retries": {"type":"int","default":1,"doc":"OpenAI SDK transport retries","group":"stt","effect":"live"},
  "stt.openai.model": {"type":"str","default":"whisper-1","doc":"whisper-1, gpt-4o-mini-transcribe, gpt-4o-transcribe, gpt-transcribe","group":"stt","effect":"live"},
  "stt.openai.streaming_model": {"type":"str","default":"gpt-live-transcribe","doc":"stt.streaming; the one model with mid-utterance deltas","group":"stt","effect":"live"},
  "stt.openai.timeout": {"type":"int","default":60,"doc":"seconds; allow self-hosted backends time to cold-start","group":"stt","effect":"live"},
