  "tool_loop_guardrails.loop_caps.max_web_searches": {"type":"int","default":50,"doc":"web_search calls per turn","group":"tool_loop_guardrails","effect":"live"},
  "tool_loop_guardrails.non_interactive_hard_stop_enabled": {"type":"bool","default":true,"doc":"Unattended gateway/cron platforms hard-stop by default (nobody can /stop a model that ignores warnings); interactive cli/tui/desktop/acp stay warning-only.","group":"tool_loop_guardrails","effect":"live"},
  "tool_loop_guardrails.warn_after.exact_failure": {"type":"int","default":2,"doc":"","group":"tool_loop_guardrails","effect":"live"},
  "tool_loop_guardrails.warn_after.idempotent_no_progress": {"type":"int","default":2,"doc":"","group":"tool_loop_guardrails","effect":"live"},
  "tool_loop_guardrails.warn_after.same_tool_failure": {"type":"int","default":3,"doc":"","group":"tool_loop_guardrails","effect":"live"},
  "tool_loop_guardrails.warnings_enabled": {"type":"bool","default":true,"doc":"","group":"tool_loop_guardrails","effect":"live"},
  "tool_output.max_bytes": {"type":"int","default":50000,"doc":"","group":"tool_output","effect":"live"},
  "tool_output.max_line_length": {"type":"int","default":2000,"doc":"","group":"tool_output","effect":"live"},
  "tool_output.max_lines": {"type":"int","default":2000,"doc":"","group":"tool_output","effect":"live"},
  "tools.connectors.enabled": {"type":"bool","default":true,"doc":"","group":"tools","effect":"live"},
  "tools.tool_search.defer": {"type":"list","default":["computer_use","session_search","image_generate","todo_list","process_manage","cronjob_manage","browser_vault","drive_preview","gui_tour","desktop_preview","annotate_preview","manage_catalog","show_tip","desktop_project","close_terminal","set_theme","read_terminal","read_window_below","focus_pane"],"doc":"Tools replaced by the bridge by default. This list intentionally includes cold, event-triggered built-ins; an explicit list replaces it wholesale and [] keeps every tool eager. The runtime fallback in tools/tool_search.py derives from this value. Desktop GUI surface (desktop_ui, project and catalog toolsets)","group":"tools","effect":"live"},
  "tools.tool_search.enabled": {"type":"str","default":"auto","doc":"Tiered: tier 0 (no deferred tools) = everything eager; tier 1 = bridge + a name+description manifest when it fits the budget (degrades to names-only); tier 2 (over budget even names-only, e.g. ~3,300-tool APIs) = bare bridge + a one-line-per-server summary (name + tool count). \"auto\"|\"on\" = activate when at least one deferred tool exists (\"auto\" is an alias of \"on\" today, reserved for a future budget-gated mode; keep it the default so explicit \"on\"/\"off\" pins are unaffected). \"off\" = pass-through, no bridge.","group":"tools","effect":"live"},
  "tools.tool_search.listing": {"type":"str","default":"auto","doc":"Catalog listing embedded in the bridge description (name + first sentence ≤60 chars, grouped by server/toolset). \"auto\" = include when it fits (falls back to names-only, then bare tier-2 bridge); \"on\" = same rendering, explicit intent; \"off\" = always the bare bridge.","group":"tools","effect":"live"},
  "tools.tool_search.listing_max_tokens": {"type":"int","default":4000,"doc":"Absolute cap on the embedded listing in tokens (chars/4), regardless of context size. Range 200..60000.","group":"tools","effect":"live"},
  "tools.tool_search.max_search_limit": {"type":"int","default":25,"doc":"Hard upper bound the model may request via `limit` (per query). Range 1..50.","group":"tools","effect":"live"},
  "tools.tool_search.search_default_limit": {"type":"int","default":5,"doc":"Hits per query when the model omits `limit`. Range 1..max_search_limit.","group":"tools","effect":"live"},
  "tools.tool_search.threshold_pct": {"type":"int","default":5,"doc":"Listing budget as % of the model's context length; effective budget = min(this % of context, listing_max_tokens). Range 0..100.","group":"tools","effect":"live"},
